CREATE OR REPLACE FUNCTION calculate_rcp(p_vehiclereg VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_distdone NUMERIC;
    v_distleft NUMERIC;
    v_total NUMERIC;
BEGIN
    SELECT distdonekm, distleftkm INTO v_distdone, v_distleft
    FROM transportinfo
    WHERE vehiclereg = p_vehiclereg;

    IF v_distdone IS NULL OR v_distleft IS NULL THEN
        RETURN NULL;
    END IF;

    v_total := v_distdone + v_distleft;

    IF v_total = 0 THEN
        RETURN 0;
    END IF;

    RETURN ROUND((v_distdone * 100.0 / v_total), 2);
END;
$$ LANGUAGE plpgsql;

